export const WIKI_ARTICLES=Object.freeze([
 {id:'retaliation-warrior-zane',title:'Retaliation Warrior · Zane’s Season 2 Setup',category:'Build Guides',readTime:'4 min',
 author:'Zane',summary:'A Retaliation Warrior built around Defense, Block Chance and counterattack multipliers, with pets, gems and upgrade priorities.',
 keywords:'warrior retaliation season 2 zane kiffens build defense block strength gems pets deflection bulwark stance critical double hit double damage incoming attacks damage formula',sections:[
  {title:'How the build works',body:"Retaliation Warrior plays differently from an attack-focused build. Enemy attacks trigger retaliation, and blocking gives that retaliation hit 50% more damage. Block Chance is therefore an offensive stat as much as a defensive one: more blocked hits means more boosted counters. The setup takes some preparation, but it can one-shot regular monsters once the core pieces are in place, while still bringing respectable boss damage."},
  {title:'Stat priority',body:"Retaliation % → Defense → Block Chance → Strength is the foundation of this setup. Retaliation and Defense are the main damage investments, while Block Chance makes the stronger blocked-hit counter more consistent. Strength comes after those priorities. Intelligence, Dexterity, regular Attack Damage, flat Attack Damage, flat Added Damage and Pet Damage are not where I would spend valuable rolls for this version of Warrior. Crit Chance, Crit Damage, Double Hit and Double Damage all work with retaliation, though, so they belong in the conversation. Their value comes down to what each roll adds to actual counter damage compared with another Retaliation or Defense roll."},
  {title:'Pets',body:"One Defense pet, one Increased Strength (% STR) pet and two Retaliation pets make a sensible four-pet foundation. This spreads the investment across the main stats instead of leaning entirely into a single bonus. Block Chance pets are an interesting alternative, particularly if more blocked counters outperform the damage gained from the second Retaliation pet. The catch is that Block Chance is a Legendary pet bonus, so that version of the setup takes more investment."},
  {title:'Gems',table:[['Slot','What I aim for'],['Belt and jewelry','Red'],['Armor, helmet, gloves and boots','Red'],['Weapon','Blue'],['Torch','Whatever fits your needs']],body:"Red gems across armor, belt and jewelry fit the stat priorities here, with blue in the weapon. For farming, swapping some armor gems to blue or orange can make sense when EXP or material income is more valuable than maximum counter damage. EXP as a secondary gem stat also has a place in a leveling setup. Torch gems are flexible depending on what the rest of the equipment is missing."},
  {title:'Skills and runes',body:"Deflection and Bulwark Stance are central to the setup. My current bonuses show +40% from Deflection and +15% from Bulwark Stance. Bulwark sets Dodge Chance to 0%, which suits a build that wants enemies to attack into its block and retaliation instead of avoiding hits. Guild Defense and Retaliation bonuses complement that approach. Immortal Bulwark and Trinity of Blood are part of the runeword setup, alongside Fury, Fortitude, Vitality, Wisdom and Precision runes. Exact rune placement and skill-point allocation depend on how far the character has progressed."},
  {title:'Build snapshot',table:[['Stat','Current value'],['Character level','196'],['Monster Level','208'],['Gear Score','2,145'],['Defense','7.67M'],['Block Chance','84%'],['Damage Reduction','97.6%'],['Strength','1.96K'],['Retaliation per enemy attack','6.76B–9.66B'],['Average retaliation per enemy attack','8.21B']],body:"These numbers are a snapshot of the build at level 196 and Monster Level 208. The character sheet shows 6.76B–9.66B retaliation per enemy attack, with an 8.21B midpoint. That range is a useful baseline for comparing upgrades; blocked-hit bonuses, crits, Double Hit and Double Damage can affect the damage seen in combat. The snapshot includes the active stance, pets, runes, guild bonuses, gems and time boost."},
  {title:'Damage interactions',body:"Retaliation can benefit from more than its own dedicated stat. Crit Chance, Crit Damage, Double Hit and Double Damage all interact with retaliation, while blocked attacks gain another 50% retaliation damage. That opens up a more interesting late-game direction: once Retaliation and Defense are high, offensive secondary effects may compete with simply stacking another direct bonus. The important comparison is the damage produced over real enemy attacks, not just the largest number on the character sheet."},
  {title:'Where the build can go next',body:"The next optimization question is where a roll gives the most value. Retaliation %, Defense and Block Chance establish the base, but the best balance could change as Crit Chance, Crit Damage, Double Hit and Double Damage become available on better gear. Strength, Guild Defense, Deflection and Bulwark also influence which upgrades are worth prioritizing. Comparing those options under the same combat conditions is the way to refine the build without assuming one stat stays best forever."},
  {title:'Try the build in Arcana',body:"The linked Build Studio setup gives the starting stat priorities, pet bonuses and rune families in one place. The equipment, pet Compound levels, exact rune positions and skill-point allocation can be adjusted around your own progression without changing the main retaliation-focused approach."}
 ],actions:[{label:'Open my Retaliation Warrior build',route:'labs/build?build=warrior-retaliation-zane',icon:'flask'},{label:'Open Pet Lab',route:'labs/pets',icon:'paw'},{label:'Open Rune Forge',route:'labs/runes?build=warrior-retaliation-zane',icon:'gem'}],source:'player-authored'},
 {id:'pet-compound',title:'Pet Compound & Equalisation',category:'Pets',readTime:'2 min',summary:'Understand Compound levels, your equipped-pet cap, and what affixes do not change.',keywords:'pet compound equalisation seasonal permanent hatch bonus weakest equipped four pets affixes all class skills',sections:[
  {title:'The quick answer',body:'Compound levels improve a pet’s main Hatch Bonus. They do not increase the pet’s separate evolved affixes. Equipped pets are subject to equalisation.'},
  {title:'Seasonal versus Permanent',body:'Seasonal characters have an equalisation allowance of 10 levels; Permanent characters have an allowance of 25 levels. The effective Compound cap is the weakest equipped level plus that allowance. An empty equipped-pet position counts as level 0.'},
  {title:'Example',body:'If equipped Compound levels are 20, 8, 12, and 12, the seasonal effective cap is 18. The +20 pet contributes its main bonus as if it were +18. Its actual Compound level is preserved.'},
  {title:'Affixes are a different system',body:'Pets can unlock up to four evolved affix slots. Affix type, rank, and reroll rules are separate from Compound. Do not use the Compound calculator to calculate an affix’s value.'}],actions:[{label:'Open Compound Calculator',route:'calculators/pet',icon:'calculator'},{label:'Configure Pet Loadout',route:'labs/pets',icon:'paw'}],source:'game-config'},
 {id:'rune-grid',title:'Rune Grid Growth',category:'Runes',readTime:'2 min',summary:'See when Monster Level expands your rune board, from 2×2 to 6×7.',keywords:'rune grid growth monster level size milestones 2x2 6x7 expansion 150 220 300',sections:[
  {title:'The quick answer',body:'The rune grid grows as Monster Level increases. Character level does not determine its dimensions, and you do not manually purchase the grid expansions.'},
  {title:'Progression milestones',table:[['Monster Level','Grid'],['Start','2 × 2'],['10','3 × 3'],['30','4 × 3'],['45','5 × 3'],['65','6 × 3'],['90','6 × 4'],['150','6 × 5'],['220','6 × 6'],['300','6 × 7']]},
  {title:'Plan without losing your work',body:'Arcana stores rune layouts separately from the currently unlocked grid size. Runes extending beyond a smaller Monster Level board become inactive, not deleted, and become available again when you raise Monster Level.'}],actions:[{label:'Open Rune Forge',route:'labs/runes',icon:'gem'},{label:'Inspect Build Studio',route:'labs/build',icon:'flask'}],source:'game-and-player-verified'},
 {id:'monster-level',title:'Monster Level Farming',category:'Progression',readTime:'3 min',summary:'Optimize Monster Level progress by comparing kills per second and XP per kill.',keywords:'monster level farming ml monster xp per kill weakest strongest exp gain frenzy early season 2 farming',sections:[
  {title:'The quick answer',body:'Monster Level progress depends on Monster Level XP earned per unit of time. Compare both kill speed and XP per kill when choosing which monster to farm.'},
  {title:'EXP Gain and Monster Level',body:'EXP Gain is for character progression, not a multiplier on Monster Level XP. Character levels still matter because they provide access to more skill points.'},
  {title:'Frenzy and Monster Level XP',body:'Frenzy kills do not award Monster Level XP. Do not include them when estimating ML XP per second or comparing farming spots. Measure normal kills that actually award Monster Level XP, rather than counting every defeat shown during Frenzy.'},
  {title:'Season 2 monster differences',body:'From Murky Depths onward, the weakest monster in a biome awards 10% less Monster Level XP and the strongest awards 10% more, relative to that biome’s normal value. Because XP now varies, the lowest-HP monster is not automatically the best farm in every biome.'},
  {title:'Choose efficiently',body:'Test several monsters. A weaker monster can still be best if it dies sufficiently faster. Calculate XP per second rather than choosing by the largest XP reward or the highest HP alone.'}],actions:[{label:'Compare ML farming speeds',route:'calculators/ml-farm',icon:'calculator'},{label:'Browse Biomes & Monsters',route:'wiki/library?kind=biome',icon:'book'},{label:'Search Monster Levels',route:'wiki/library?kind=monster',icon:'search'}],source:'official-patch',sourceUrl:'https://idlearc.com/patch-notes/1-3-1'},
 {id:'season-2',title:'Season 2 Essentials',category:'Getting Started',readTime:'3 min',summary:'The core systems that matter when planning a new Season 2 character.',keywords:'season 2 guide beginner start forge equipment gems raids druid torch guild',sections:[
  {title:'Your character',body:'Season 2 added the Druid as a fifth class. Your class has three skill branches, and the passive tree and class tree use separate point allocations.'},
  {title:'Equipment and upgrades',body:'The Forge tracks upgrade progression on gear slots. Equipment items can be switched without losing that slot’s upgrade progression. A Torch has its own separate slot.'},
  {title:'Runes and pets',body:'The rune grid grows with Monster Level. Rune families provide primary stats, and placed runes can have a chosen secondary. Compound affects a pet’s main Hatch Bonus, while evolved affixes follow separate rules.'},
  {title:'Raids and community',body:'Rift Raids are cooperative fights for groups of two to four. ArcanaLFG helps you find a group and coordinate without replacing the in-game raid finder.'}],actions:[{label:'Open Character Planner',route:'labs/build',icon:'flask'},{label:'Explore Raid Groups',route:'lfg/raids',icon:'users'}],source:'official-patch',sourceUrl:'https://idlearc.com/patch-notes/1-3-1'},
 {id:'guide-builds',title:'Inspect a Complete Guide Build',category:'Build Guides',readTime:'2 min',summary:'See how a full guide build opens directly in Build Studio, ready to inspect or copy.',keywords:'guide interactive inspect full build studio copy equipment runes pets skills sharing',sections:[
  {title:'A guide is a starting point',body:'A connected guide can include equipment, rune layout, pet setup, class skills, passive allocations, and explanatory notes as one inspectable package.'},
  {title:'Inspect, then make a copy',body:'Open the embedded build in Build Studio to examine its configuration. Copy it into a local draft before making changes. The published guide build remains unchanged.'},
  {title:'Learn while experimenting',body:'Tap an item to open its reference, compare it, or send it to Upgrade Costs. Rune and pet selections can be explored in their dedicated Labs tools without rebuilding the loadout from scratch.'},
  {title:'Demonstration status',body:'The available Warrior example illustrates the connected workflow. It is not a verified or recommended endgame build.'}],actions:[{label:'Open Demonstration Guide',route:'wiki/guide?id=warrior-retaliation-demo-guide',icon:'book'},{label:'Open Build Studio',route:'labs/build',icon:'flask'}],source:'arcana-workflow'},
{id:'guild-planning',title:'Guild Skill Tree Planning',category:'Guilds',readTime:'3 min',summary:'Understand guild points, rank gates, Mastery and the Ascension families before spending.',keywords:'guild tree guild points vanguard finesse fortune mastery ascension rank unlock bonus boost guild level',sections:[
  {title:'How guild points work',body:'A guild earns one skill point per guild level through level 68. Each level after 68 supplies two points. The eleven base bonuses are grouped into Vanguard, Finesse and Fortune.'},
  {title:'Rank unlocks',table:[['Ranks','Requirement'],['1–3','Available from the start'],['4–6','15 total points already allocated'],['7–10','35 total points already allocated'],['Mastery and Family ranks','68 allocated points']]},
  {title:'Planning Ascension',body:'Mastery raises all base bonus categories and is capped by guild levels above 68. Family ranks amplify a whole row, with additional cross-family unlock requirements at higher ranks.'},
  {title:'Compare and share safely',body:'Choose a guild level, allocate points and compare totals in Arcana. You can undo or redo changes, and a share link preserves your plan. Editing the plan does not spend in-game guild points.'}],actions:[{label:'Open Guild Skill Tree Planner',route:'labs/guild-tree',icon:'shield'},{label:'Find guild recruitment',route:'lfg/guilds',icon:'users'}],source:'game-config',sourceUrl:'https://idlearc.com/patch-notes/1-3-1'},
 {id:'pet-affix-costs',title:'Pet Affix Upgrades & Shards',category:'Pets',readTime:'3 min',summary:'Plan evolved affix levels and distinguish shard costs from Compound bonuses.',keywords:'pet affix upgrade costs shards all class skills ACS evolve extra kill reroll slots pity',sections:[
  {title:'Affixes are separate from Compound',body:'Compound raises a pet’s main Hatch Bonus. Evolved affixes have their own slots, types, levels and upgrade costs. The systems are not interchangeable.'},
  {title:'Upgrade shard costs',body:'For ordinary evolved affixes, the recorded configuration uses the next level divided by 20, rounded up, as the Pet Shard cost for each rank. Arcana sums these individual steps from your current level to the target.'},
  {title:'Special affix limits',body:'All Class Skills has a maximum evolved level of 2 and uses a special upgrade cost of 1,000 Pet Shards. Extra Kill Chance has a maximum evolved level of 1. The calculator applies these individual limits instead of treating every affix identically.'},
  {title:'Slots and rerolls',body:'Pets start with two evolved affix slots and can hold up to four. The October 9 configuration lists a 5-shard cost for unlocking an additional affix slot and 5 shards for an affix reroll. These are distinct from the cost of upgrading an affix level.'}],actions:[{label:'Open Pet Affix Cost Calculator',route:'calculators/affixes',icon:'calculator'},{label:'Browse Pet Affixes',route:'wiki/library?kind=pet-affix',icon:'paw'},{label:'Pet Compound guide',route:'wiki/article?id=pet-compound',icon:'book'}],source:'game-config'},
 {id:'forge',title:'The Forge & Gear Slot Progression',category:'Equipment',readTime:'3 min',summary:'Learn why upgrading a gear slot is different from upgrading an individual item.',keywords:'forge slot item rarity reforge enhance awaken pity gear progression equipment upgrade season 2',sections:[
  {title:'What the Forge upgrades',body:'In Season 2, gear-slot progression carries tier, enhancement and awakening. Swapping an item into an upgraded slot keeps that slot’s progression, so you can compare alternative equipment bases without starting upgrades over.'},
  {title:'Items and affixes still matter',body:'Your equipped item determines its own base characteristics and modifiers. Tier changes unlock affix positions, and the Forge has its own item and material requirements. A new weapon is not automatically superior because it is rarer.'},
  {title:'Before calculating costs',body:'Select the item or equipment base in the Codex, then open Upgrade Costs or Compare Equipment with that choice. Arcana distinguishes configured tier-change costs from total projected enhancement, pity or awakened costs when those totals cannot be verified.'},
  {title:'Reforging is a different action',body:'Reforge combines three identical items into one of the next rarity. It is separate from the slot progression of the Forge.'}],actions:[{label:'Open Upgrade Cost Calculator',route:'calculators/upgrade',icon:'calculator'},{label:'Compare equipment',route:'calculators/compare',icon:'compare'},{label:'Browse equipment',route:'wiki/library?kind=item',icon:'shield'}],source:'official-patch',sourceUrl:'https://idlearc.com/patch-notes/1-3-1'},
 {id:'gems',title:'Sockets, Gems & Equipment Slots',category:'Equipment',readTime:'3 min',summary:'Start with socket unlocks, then understand why the same gem behaves differently across equipment slots.',keywords:'gems sockets gem dust garnet jade lapis amber flawless socket unlock monster level jewelry belt torch',sections:[
  {title:'When sockets become available',body:'The Season 2 socket system begins at Monster Level 20. Every class has the same 20-socket progression, with sockets unlocked and leveled using gold.'},
  {title:'Gem families and rarities',body:'Gems appear in four families: Garnet, Jade, Lapis and Amber. Each family has multiple rarities, and a gem’s benefit changes with its equipped location: weapon, Torch, armor or jewelry.'},
  {title:'Improving gems',body:'Three gems can be fused into the next rarity. Unneeded gems can be salvaged into Gem Dust, while recutting allows bonus statistics to be changed. Flawless gems are special rare drops.'},
  {title:'Plan in context',body:'Choose gems around the equipment positions and damage or survival mechanics your build actually uses. A gem useful in one slot is not guaranteed to provide the same benefit in another.'}],actions:[{label:'Open Build Studio',route:'labs/build',icon:'flask'},{label:'Browse equipment',route:'wiki/library?kind=item',icon:'shield'}],source:'official-patch',sourceUrl:'https://idlearc.com/patch-notes/1-3-1'},
 {id:'rift-raids',title:'Rift Raid Basics',category:'Raids',readTime:'2 min',summary:'Find a team, understand the strike and reward loop, and prepare a usable build.',keywords:'rift raid titan might group party ready check strike rewards chests lfg raid classes',sections:[
  {title:'How a raid works',body:'Rift Raids are cooperative encounters for two to four players against a Rift Titan scaled to the group’s Might. Each member takes one 30-second strike and receives graded rewards and Spoils Chests.'},
  {title:'Prepare your loadout',body:'A raid build can prioritize different equipment, skill allocations, pets and runes than an everyday farming build. Inspect your current setup in Build Studio before joining.'},
  {title:'Finding a group',body:'ArcanaLFG helps players coordinate parties and discover listings. It complements the in-game Rift Raid system; the raid itself still takes place in IdleArc.'}],actions:[{label:'Find Rift Raid groups',route:'lfg/raids',icon:'users'},{label:'Open Build Studio',route:'labs/build',icon:'flask'},{label:'Season 2 essentials',route:'wiki/article?id=season-2',icon:'book'}],source:'official-patch',sourceUrl:'https://idlearc.com/patch-notes/1-3-1'},
 {id:'drop-rarities',title:'Equipment Rarity & Drop Progression',category:'Equipment',readTime:'2 min',summary:'Understand early rarity unlocks, item alternatives and why farming speed still matters.',keywords:'item drop rarity uncommon rare epic legendary ml monster level reforge forge drop bonus gilded lucky',sections:[
  {title:'Rarity unlock milestones',table:[['Item rarity','Possible drops from Monster Level'],['Uncommon','10'],['Rare','45'],['Epic','90'],['Legendary','150']]},
  {title:'Possible does not mean guaranteed',body:'These are the earlier Monster Levels where rare items can begin dropping at small chances, not guaranteed milestones. The drop’s specific bonus and modifiers still matter.'},
  {title:'Reforge and compare',body:'Combining three identical items reforges them into an item of the next rarity. In the Codex you can compare an equipment base by its configured implicit-stat ranges, then open the Forge cost reference for its tier progression.'},
  {title:'Build around purpose',body:'An item with the right effects for a farming build can be useful even when a different base has a larger raw stat. Compare what each item contributes to your actual build rather than treating rarity as a complete ranking.'}],actions:[{label:'Browse Item Codex',route:'wiki/library?kind=item',icon:'shield'},{label:'Compare equipment',route:'calculators/compare',icon:'compare'},{label:'Read Forge guide',route:'wiki/article?id=forge',icon:'book'}],source:'official-patch',sourceUrl:'https://idlearc.com/patch-notes/1-3-1'},

 {"id":"convergence-complete-guide","title":"Convergence: Complete Season 2 Guide","category":"Mechanics","readTime":"18 min","summary":"A practical Season 2 guide to unlocking Convergence, raising tiers, managing monster seats, building the 37-node Lattice, and choosing a farming strategy.","keywords":"convergence convergence level lattice convergence tier wildcall elites elite pity monster level ML350 resonance keystones seats might bastion harvest fortune ascendance wild eternal sigil primeval core","sections":[{"title":"What Convergence is","body":"Convergence is an endgame progression system built around a personal set of monster seats and a 37-node Convergence Lattice. Once unlocked, you fill seats with monsters and defeat them to raise Convergence Tier. Higher tiers make those monsters harder and improve selected rewards. The Lattice lets you specialize that loop toward damage, survival, materials, gold and item quality, Monster Level progression, or elite farming. The system is therefore both a challenge ladder and a build tree: a high tier is not automatically better if it slows kills so much that your progress or rewards per hour fall."},{"title":"How to use this guide","body":"This guide brings together Convergence’s listed settings and Arcana’s overview of the mode. Some underlying formulas and event rules are not shown in the game, so those details are called out as uncertain instead of guessed. Updates can change costs and effects; check the current in-game screen before committing points or changing your setup."},{"title":"At a glance","table":[["Setting","Current reference"],["Unlock","Monster Level 350"],["Lattice","37 nodes in Core plus six branches"],["Seats","Up to 6; two free Lattice loadouts; up to 3 loadouts"],["Tier steps","Automatic tier increase every 200 kills"],["Death penalty","Normally −5 tiers; Undying changes this to −2 and respawns after 3 seconds"],["Base elite chance","1%; Wildcall adds 0.2 percentage points per rank on a wild kill"],["Elite pity field","300"],["Tier-0 monster baselines","1,150 HP and 15 damage"],["Progress multiplier","11"],["Last reviewed","October 23, 2026; check the live game for current values"]],"body":"The table reports settings values, not a promise that every character sees an identical outcome. Existing bonuses, tier, selected monsters, game mode, and later balance changes can affect the live result."},{"title":"Unlock and first setup","body":"Convergence unlocks at Monster Level 350. After unlocking, Convergence presents monster seats and a Lattice. A seat is a monster slot for the Convergence encounter; the live overview describes filling seats with chosen monsters, while the game reference distinguishes wild seats and locked seats in reward rules. Convergence supports up to six seats, two free Lattice loadouts, and three loadouts total. A third loadout is listed at a cost of 500. Check the in-game prompt to confirm the currency before spending.\n\nA practical first session: unlock the feature, note your starting tier and progress, select monsters you can defeat quickly, and record kills per minute and deaths. Then spend a small number of points in the branch that improves your immediate bottleneck. Keep a baseline before changing nodes; that makes it easier to tell whether more damage, more survivability, or a reward specialization actually improved the loop."},{"title":"How Convergence Tier rises and falls","body":"Convergence rises by one tier every 200 kills; this is separate from Monster Level progression. A normal death drops five tiers. The Undying notable in Bastion changes the death loss to two tiers and sets respawn time to three seconds. Undying's description also says monster-level progress is not lost on death.\n\nThe game does not make the kill-counter reset rule, partial progress after death, minimum tier, or effect of changing seats clear. Check the live progress indicator rather than assuming progress resets or carries over. For planning, expect a meaningful tradeoff: a 200-kill climb can be erased quickly by a death without Undying, so stable clear speed can be more valuable than pushing one tier higher."},{"title":"Monster scaling and progression","table":[["Setting","Value","Safe interpretation"],["Convergence progress multiplier","11","A configured progress multiplier; its exact placement in the live equation is not exposed."],["Monster base HP","1,150","Configured baseline; tier and encounter effects can raise actual HP."],["Monster base damage","15","Configured baseline; tier and encounter effects can raise actual damage."],["HP scaling coefficients","1, 0.1, 0.001","Constant, linear, and quadratic tuning fields; formula and variable are not confirmed by the game."],["Damage scaling coefficients","1, 0.03, 0.0002","Constant, linear, and quadratic tuning fields; formula and variable are not confirmed."],["Thick Skin coefficients","1, 0.015, 0.0001","A second scaling set associated with Thick Skin; do not treat these as a verified multiplier formula."],["Resonance scaling","1 + 0.05 linear field","listed coefficient; exact calculation and rounding are not specified."],["Yield scaling","1 + 0.03 linear field","listed coefficient; exact calculation and rounding are not specified."],["Wild drop bonus","0.25","Configured wild drop bonus field; scope and stacking are not fully described."]],"body":"The listed coefficients show that monster health, damage, Resonance, and yield scale as you progress, but the game does not show the full calculation. It would be guesswork to turn them into exact tier-by-tier totals, so use the live stats and reward panel to judge your current tier."},{"title":"Resonance, yield, and the reward loop","body":"The game contains separate scaling fields for Resonance and yield, and the lattice has multiple direct bonuses to both. Attunement increases Resonance by 1.5% per rank. Crucible doubles Resonance and yield while also increasing the HP and damage of monsters at your tier. Bastion's Aegis keystone instead reduces Resonance by 20%; Vanguard trades 40% material yield for 40% Monster Level progress. These are explicit tradeoffs, not universally positive multipliers.\n\nThe game does not clearly explain how every reward currency works or how global bonuses combine with Lattice bonuses. Compare the reward panel across repeatable runs instead of multiplying every percentage together."},{"title":"Elite encounters","table":[["Elite setting","Current reference"],["Base elite chance","1%"],["Wildcall contribution","+0.2 percentage points per rank on a wild kill; Wildcall max rank 10"],["Pity counter","300"],["Elite HP multiplier","×6"],["Elite reward multiplier","×6"],["Elite Resonance multiplier","×10"],["Bonus materials","3"],["Shards","5–15"],["Feral","Elite chance ×2 and elite rewards ×1.5"],["Elite Echo","Elite kills count as ×25 Monster Level progress"]],"body":"A 300-kill elite-pity value is listed, but the game does not clarify the counter’s scope, reset condition, or whether an elite is guaranteed on that exact kill. Treat 300 as a useful reference, not a promise. Likewise, do not infer that bonus materials, shard range, reward multiplier, and every drop chance are all multiplied together. Record several elite outcomes if you want to estimate the live average."},{"title":"Elite loot nodes","body":"Harvest's Sigil Echo gives elites an 8% Eternal Sigil chance and a 4% Primeval Core chance. The game does not clarify whether these rolls are independent, affected by other drop bonuses, or able to award both items at once.\n\nFortune's Treasure Elite makes elites always drop an item and chooses the item tier as the best of three rolls. Gem Vein makes elites always drop a gem at +20 quality. These are powerful guarantees for elite-focused farming, but they apply to elites; the game does not say that they guarantee the same drops from ordinary Convergence kills."},{"title":"The 37-node Lattice","table":[["Group","Node count","What the branch emphasizes"],["Core Attunement","1","Resonance"],["Might","6","Attack, pets, retaliation, critical damage, execution and carry-over damage"],["Bastion","6","Damage reduction, health, tier damage control and death recovery"],["Harvest","6","Materials, fragments, overflow conversion and cross-seat materials"],["Fortune","6","Gold, item/rune/gem odds and better elite drops"],["Ascendance","6","Monster Level progress and XP"],["Wild","6","Wild-seat elite frequency and elite rewards"]],"body":"The Lattice has six themed constellations and a central Core Attunement node: seven groups and 37 nodes in total. In the lists below, “rank” refers to the node's listed rank cap. A node described as a notable or keystone has a special effect rather than a normal per-rank bonus."},{"title":"Core Attunement","table":[["Node","Effect","Cap or cost"],["Attunement","+1.5% Resonance per rank","20 ranks; 1 point per rank"]],"body":"This is the one-node center of the Lattice. It is the direct Resonance investment. Because the Lattice points are finite and the game does not show exactly how Resonance converts to rewards, compare the resulting Resonance and rewards in your own setup before maxing it by habit."},{"title":"Might: damage and finishing","table":[["Node","Effect","Cap or condition"],["Ferocity","+2% attack, pet, and Retaliation damage per rank","15 ranks"],["Brutality","+2% critical damage per rank","10 ranks"],["Overkill","Excess damage on a killing blow carries into the next monster","Notable; after 5 Convergence points; listed cost 5"],["Executioner’s Mark","Instantly kills a monster below 8% HP","Notable; elites are immune"],["Crucible","Monsters at your tier gain +100% HP and damage; Resonance and yield ×2","Keystone; max 2 keystones equipped"],["Might Star","+1% attack, pet, and Retaliation damage per endless rank","Requires Might minor nodes maxed"]],"body":"Might is the straightforward damage branch, with an important warning: Crucible doubles the HP and damage of same-tier monsters. It can improve Resonance and yield, but also lengthens or destabilizes the fight. Overkill can reduce wasted damage on ordinary kills. Executioner's threshold is 8% HP, but its explicit elite immunity means it is not an elite execute."},{"title":"Bastion: defense and death recovery","table":[["Node","Effect","Cap or condition"],["Warden","−2% damage taken per rank; multiplicative reduction","15 ranks; subject to 70% damage-taken reduction cap"],["Vitality","+3% maximum HP per rank","10 ranks"],["Thick Skin","Halves the growth of tier-based monster damage","Notable"],["Undying","Death costs no Monster Level progress; tier loss becomes 2 rather than 5; 3-second respawn","Notable"],["Aegis","−35% damage taken and −20% Resonance","Keystone; max 2 keystones equipped"],["Bastion Star","−0.25% damage taken per endless rank","Endless"]],"body":"Warden's reduction is listed as multiplicative and has a 70% cap. Do not add every damage-reduction source as if it were a simple sum. Aegis has a clear offensive cost: minus 20% Resonance. Undying is particularly attractive when deaths are wiping out long kill streaks, but it still costs two tiers and three seconds per death."},{"title":"Harvest: materials and conversion","table":[["Node","Effect","Cap or condition"],["Bountiful","+3% material yield per rank","15 ranks"],["Refinement","+3% fragment and essence drop chance per rank","10 ranks"],["Overflow","Drop chance above 100% converts into extra quantity","Notable"],["Sigil Echo","Elite chance of 8% Eternal Sigil and 4% Primeval Core","Notable"],["Cornucopia","Each kill rolls materials for every other locked seat at 30%; wild seats drop no materials","Keystone"],["Harvest Star","+0.5% material yield per endless rank","Endless"]],"body":"Overflow is a conversion rule: excess chance is not simply wasted once the relevant chance passes 100%. The game does not say whether this rule applies to every chance stat. Cornucopia's wording distinguishes locked seats and wild seats, so it should not be paraphrased as “every seat always pays materials.” Test which seats qualify in the current interface."},{"title":"Fortune: currency and item quality","table":[["Node","Effect","Cap or condition"],["Gilded","+3% gold per rank","15 ranks"],["Prospector","+2% item, rune, and gem drop chance per rank","10 ranks"],["Treasure Elite","Elites always drop an item; item tier is the best of 3 rolls","Notable"],["Gem Vein","Elites always drop a gem at +20 quality","Notable"],["Midas","Gold ×1.5; XP ×0.5","Keystone"],["Fortune Star","+0.5% gold per endless rank","Endless"]],"body":"Prospector concerns drop chance, while Treasure Elite and Gem Vein add elite-specific guarantees. Midas is a deliberate exchange: 50% more gold for half XP. It is a poor fit if your current goal is leveling, even if gold is your most visible reward."},{"title":"Ascendance: Monster Level and XP","table":[["Node","Effect","Cap or condition"],["Momentum","+2% Monster Level progress per kill","10 ranks"],["Sage","+3% XP","15 ranks"],["Elite Echo","Elite kills count as ×25 Monster Level progress","Notable"],["Sprint","After gaining a new Monster Level, next 500 kills gain +50% progress","Notable"],["Vanguard","+40% Monster Level progress; material yield ×0.6","Keystone"],["Ascendance Star","+0.4% Monster Level progress per endless rank","Endless"]],"body":"Ascendance is for players who value Monster Level progression, not general loot. Momentum raises progress on kills, Elite Echo gives a large progress count to elite kills, and Sprint adds a temporary 500-kill window after a new Monster Level. Vanguard converts some material income into progress. The game does not document how these sources stack or whether the ×25 elite count is applied before or after other progress bonuses."},{"title":"Wild: seats and elite rewards","table":[["Node","Effect","Cap or condition"],["Wildcall","+0.2 percentage points of elite chance per rank on a wild kill","10 ranks"],["Bounty","+10% elite rewards per rank","10 ranks"],["Extra Seat I","+1 seat","Seat cap 6"],["Extra Seat II","+1 seat","Seat cap 6"],["Feral","All seats become wild; elite chance ×2; elite rewards ×1.5","Keystone"],["Wild Star","+1% elite rewards per endless rank","Endless"]],"body":"Wild is the elite-oriented branch. Wildcall improves elite frequency from wild kills; Bounty scales elite rewards; two extra-seat nodes increase the number of available monster slots up to the configured six-seat limit. Feral changes every seat to wild and multiplies elite chance and rewards. This makes Feral's seat-wide effect important: seat type also matters to Cornucopia, which says wild seats drop no materials."},{"title":"Keystones and loadout tradeoffs","body":"You can equip at most two keystones at once. The named choices are Crucible (harder same-tier monsters for doubled Resonance and yield), Aegis (large damage reduction for lower Resonance), Midas (more gold for less XP), Vanguard (more Monster Level progress for less material yield), and Feral (all-wild seats, more elite chance, and better elite rewards).\n\nThese are distinct farming modes rather than a single best pair. Choose around the resource you are actually targeting and the fights you can sustain. For instance, Crucible plus a fragile setup may erase its reward gain through slower kills and tier losses. Vanguard makes sense when Monster Level progress is the goal and its material penalty is acceptable. Midas is specifically incompatible with maximizing XP at the same time. The game does not make clear whether keystones can be swapped freely or at a cost, so check the Lattice screen before changing them."},{"title":"Endless Star ranks","body":"Each branch has a Star node after its minor nodes are maxed. The star effects are: Might +1% attack, pet, and Retaliation damage per rank; Bastion −0.25% damage taken per rank; Harvest +0.5% material yield per rank; Fortune +0.5% gold per rank; Ascendance +0.4% Monster Level progress per rank; and Wild +1% elite rewards per rank. These are described as endless ranks, meaning these ranks have no listed cap. It includes star-cost tuning fields (base 1 and every 20), but does not spell out the complete point-cost formula; use the live cost shown by the Lattice."},{"title":"Seats, wild monsters, and materials","body":"The live system overview describes assigning monsters to seats, with wild monsters and rare elites forming part of the Convergence encounter. The game reference sets a six-seat maximum and includes Extra Seat I and II. It also sets a wild drop bonus field of 0.25 and has Wildcall and Feral bonuses that refer to wild kills or wild seats.\n\n“Wild” and “elite” are separate attributes in Convergence. A wild kill is the trigger named for Wildcall; elite status controls the listed elite HP/reward multipliers and the elite-only loot nodes. Cornucopia's special wording says wild seats drop no materials, so an all-wild Feral setup can have a different material profile from a mixed-seat setup. The game does not fully explain the monster selection pool or every rule for rerolling and replacing a seated monster."},{"title":"Build paths by goal","table":[["Goal","Nodes to evaluate","Main cost or risk"],["Stable pushing","Warden, Vitality, Thick Skin, Undying; then damage as needed","Slower kills if survival is overbuilt"],["Fast ordinary clears","Ferocity, Overkill, possibly Executioner’s Mark","Executioner does not affect elites"],["Materials","Bountiful, Refinement, Overflow, Harvest Star; compare Cornucopia","Wild seats are excluded from Cornucopia materials"],["Elite loot","Wildcall, Bounty, Treasure Elite, Gem Vein, Sigil Echo; consider Feral","Elite chance and drops remain RNG; elite fights are 6× HP"],["Gold","Gilded, Fortune Star, Midas","Midas halves XP"],["Monster Level","Momentum, Elite Echo, Sprint, Vanguard, Ascendance Star","Vanguard reduces material yield to 60%"],["Resonance/yield experiment","Attunement or Crucible","Crucible doubles same-tier HP and damage; Aegis reduces Resonance"]],"body":"This table is a starting map, not a ranked build list. The best branch depends on kill speed, death frequency, and which reward matters to you. Use comparable sessions and compare output per minute or per hour; comparing one unusually lucky elite to one ordinary run will produce a misleading result."},{"title":"A practical test plan","body":"1. Record current Convergence Tier, seats, active keystones, Lattice ranks, kill time, deaths, and the resource you care about.\n2. Farm a fixed time window or a fixed number of kills with a stable monster set. Record kills, tier movement, elite count, and actual rewards.\n3. Change one major factor—such as a survival node, one keystone, or an elite node—while keeping other variables as close as possible.\n4. Repeat the same window. Compare kills per minute, deaths per 1,000 kills, elite count, and rewards per minute. For stochastic drops, repeat several windows.\n5. Keep the change only if it improves the target metric enough to justify its costs. A larger reward per kill can still be worse if the build kills much more slowly."},{"title":"What to expect when you start","body":"Expect a gated system at ML350, a setup phase for seats and a Lattice, and a grind measured in kills. The basic tier rhythm is legible—one increase per 200 kills—but death can set the climb back five tiers unless Undying softens the loss. Expect monster stats to rise with tier, although the game does not show the full per-tier formula. Expect rare elite encounters to be disproportionately durable and rewarding: the settings lists 6× HP, 6× rewards, and 10× Resonance, alongside special elite drop nodes. Expect specialization to matter: Harvest, Fortune, Ascendance, Bastion, and Wild all optimize different outcomes and some keystones exchange one resource for another."},{"title":"What to verify in-game","body":"The game does not show the full tier-based formulas for monster HP, damage, Resonance, or yield, or clarify how the 300-kill elite-pity counter resets; detailed interaction order for bonuses; every point cost and unlock prerequisite; whether the 500-unit loadout unlock is gold or another currency; whether Sigil Echo rolls are independent; the full wild/elite monster selection rules; or all state persistence rules after death, seat edits, and loadout changes. Those points should be checked against live gameplay or a newer underlying dump before being presented as exact mechanics."},{"title":"Quick reference","table":[["Question","Answer"],["When does it unlock?","Monster Level 350."],["How many kills per tier?","Automatic increase every 200 kills."],["What happens on death?","Usually −5 tiers; Undying changes it to −2 and a 3-second respawn."],["How many seats?","Up to 6."],["How many keystones?","At most 2."],["What is base elite chance?","1%; Wildcall adds 0.2 percentage points per rank for wild kills."],["How tough are elites?","Configured at 6× monster HP."],["Which node always grants elite items?","Treasure Elite; tier is best of three rolls."],["Which node guarantees elite gems?","Gem Vein; +20 quality."],["Which keystone gives more gold?","Midas: ×1.5 gold, ×0.5 XP."],["Which keystone advances ML faster?","Vanguard: +40% progress, ×0.6 material yield."]]},{"title":"Sources and update note","body":"Use the current Convergence and Lattice screens in IdleArc to confirm costs, caps, and effects before investing points. Arcana’s Convergence overview covers the unlock, monster seats, tier progression, and the 37-node Lattice. Values may change with updates; this guide was last reviewed October 23, 2026."}],"actions":[{"label":"Open Build Studio","route":"labs/build","icon":"flask"}],"connections":{"articles":["monster-level","season-2"],"collections":["monster","material"],"tools":["build"]},"source":"game-config","sourceLabel":"IdleArc 1.3.1 notes","sourceUrl":"https://idlearc.com/patch-notes/1-3-1"},
 BRUTO_PROGRESSION_GUIDE,
 ...CLASS_OVERVIEWS
]);
